import assert from 'node:assert/strict';
import {readFileSync,readdirSync,existsSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {dirname,resolve} from 'node:path';
const dir='docs/research/evidence/task-22/';
const name=readdirSync(dir).filter(n=>n.startsWith('wbs65-jpeg-measure-')).sort().at(-1);
const r=JSON.parse(readFileSync(dir+name,'utf8'));
const hash=p=>createHash('sha256').update(readFileSync(p)).digest('hex');
assert.equal(r.provenance.measurementScriptSha256,hash('scripts/measure-jpeg-wbs65.mjs'));
assert.equal(r.provenance.validatorSourceSha256,hash('src/core/jpeg-validation.ts'));
assert.equal(r.provenance.compiledValidatorSha256,hash('dist/src/core/jpeg-validation.js'));
assert.equal(r.provenance.packageLockSha256,hash('package-lock.json'));
const d=r.search.selectedMaxAccepted;
assert(d.byteLength<=10485760 && d.accounting<=134217728 && d.accepted);
assert.equal(r.search.fullTailVerification.complete,true);
const tail=r.search.history.filter(x=>x.phase==='exhaustive-tail');
assert.equal(tail.length,r.search.fullTailVerification.endDimension-r.search.fullTailVerification.startDimension+1);
tail.forEach((x,i)=>assert.equal(x.dimension,r.search.fullTailVerification.startDimension+i));
assert(tail.filter(x=>x.dimension>d.dimension).every(x=>!x.accepted));
assert.equal(r.samples.all.length,5);
r.samples.all.forEach(x=>{assert.equal(x.sha256,d.sha256);assert.equal(x.byteLength,d.byteLength);assert.equal(x.status,'accepted');});
const median=a=>[...a].sort((a,b)=>a-b)[2];
assert.equal(r.samples.medians.wallMs,median(r.samples.all.map(x=>x.wallMs)));
assert.equal(r.samples.medians.maxRSSKiB,median(r.samples.all.map(x=>x.maxRSS)));
const flat=JSON.parse(readFileSync(dir+'wbs65-flat-2026-10-24T05-18-19.377Z.json','utf8'));
assert.equal(flat.nodeArchive.actual,flat.nodeArchive.expected);assert.equal(flat.nodeArchive.matched,true);
assert.equal(flat.observations[0].child.status,'accepted');assert.equal(flat.observations[1].child.error,'jpeg_resource_limit');
for(const file of ['docs/research/jpeg-runtime-validation.md','docs/research/wbs65-jpeg-traceability.md','docs/research/wbs65-image-race-coverage.md','docs/agent/handoffs/wbs65-pr21-residual.md']){
 const text=readFileSync(file,'utf8');
 for(const m of text.matchAll(/\]\(([^)]+)\)/g)){
  const target=m[1].split('#')[0];if(!target||/^https?:/.test(target))continue;
  assert(existsSync(resolve(dirname(file),target)),`${file}: broken link ${target}`);
 }
}
console.log(JSON.stringify({evidence:name,checks:'PASS',tailProbes:tail.length,selectedDimension:d.dimension,samples:5,medianMs:r.samples.medians.wallMs}));
